<?php
declare(strict_types=1);
if(!getenv('DOCUMENT_TEST_DB_HOST')){echo "SKIP conversation data: isolated DB missing\n";exit;}
require __DIR__.'/generated_file_catalog_mysql_test.php';
require_once dirname(__DIR__).'/includes/Files/ConversationDataRepository.php';
preg_match('/CREATE TABLE IF NOT EXISTS `ProjectSources` \(.*?\) ENGINE=.*?;/s',$schema,$m);
$db->query(str_replace(['CREATE TABLE IF NOT EXISTS','utf8mb4_0900_ai_ci'],['CREATE TEMPORARY TABLE','utf8mb4_unicode_ci'],$m[0]));
$db->query("INSERT INTO Projects(id_,user_id_,name,slug,root_prefix) VALUES(500,1,'Panel','panel','Data/panel/'),(501,2,'Otro','other-panel','Data2/panel/')");
$db->query("INSERT INTO ChatSessions(id_,user_id_,title,model_id,project_id_,meta) VALUES(50,1,'Panel one','fixture',500,'{}'),(51,1,'Panel two','fixture',500,'{}'),(52,1,'Standalone','fixture',NULL,'{}'),(53,2,'Other owner','fixture',501,'{}')");
$first=$attach->attach(1,50,7100);$second=$attach->attach(1,51,7500);$standalone=$attach->attach(1,52,7600);
$repo=new ConversationDataRepository($db);
$operations=count(Config::$s3->gets)+count(Config::$s3->heads)+count(Config::$s3->puts);
$one=$repo->listing(1,50);
workCheck(count(Config::$s3->gets)+count(Config::$s3->heads)+count(Config::$s3->puts)===$operations,'Opening the catalog performs no S3 or processing calls');$oneIds=array_column($one['files'],'id');
workCheck(in_array((int)$first['id_'],$oneIds,true),'Panel contains the real ArcadeCloud working copy');
workCheck(!in_array((int)$second['id_'],$oneIds,true)&&!in_array((int)$standalone['id_'],$oneIds,true),'Session scope excludes sibling and unrelated conversation files');
workCheck((bool)array_filter($one['files'],static fn($f)=>$f['role']==='result'&&(int)$f['source_file_id']===7100),'Panel includes registered JSON linked through the original, not just the copy');
$all=$repo->listing(1,50,'project');$allIds=array_column($all['files'],'id');
workCheck(in_array((int)$second['id_'],$allIds,true)&&!in_array((int)$standalone['id_'],$allIds,true),'Project scope includes sibling attachments and isolates standalone files');
$denied=false;try{$repo->listing(2,50);}catch(DocumentAccessDenied){$denied=true;}workCheck($denied,'Another user cannot open a session panel');
$denied=false;try{$repo->listing(1,52,'project');}catch(DocumentAccessDenied){$denied=true;}workCheck($denied,'Standalone conversation cannot request an arbitrary project');
$denied=false;try{$repo->requireFile(1,50,'session',(int)$second['id_']);}catch(DocumentAccessDenied){$denied=true;}workCheck($denied,'Delivery revalidates scope even for another owned file');
$derived=array_values(array_filter($one['files'],static fn($f)=>$f['role']==='result'))[0];
$db->query("UPDATE FileS3 SET Found=0 WHERE id_=7100");
$revoked=$repo->listing(1,50);
workCheck(!in_array($derived['id'],array_column($revoked['files'],'id'),true)&&!in_array((int)$first['id_'],array_column($revoked['files'],'id'),true),'Revoked source hides both working copy and JSON');
$denied=false;try{$repo->requireFile(1,50,'session',$derived['id']);}catch(DocumentAccessDenied){$denied=true;}workCheck($denied,'A previously listed JSON cannot be delivered after revocation');
$db->query("UPDATE FileS3 SET Found=1 WHERE id_=7100");
$db->query("UPDATE ChatSessions SET meta=JSON_SET(meta,'$.detached_file_ids',JSON_ARRAY(".(int)$first['id_'].")) WHERE id_=50");
workCheck(!$repo->listing(1,50)['files'],'Unlinked copy also removes its derived results from this conversation');
$db->query("INSERT INTO ProjectSources(id_,project_id_,files3_id_,s3_key,filename) VALUES(990,500,9990,'Data/registry/source.txt','source.txt')");
$projectSource=$repo->listing(1,50);
workCheck((bool)array_filter($projectSource['files'],static fn($f)=>$f['id']===9990&&$f['origin']==='project'&&$f['session_id']===null),'Published project source appears with project scope and no invented conversation');
$db->query('DELETE FROM ProjectSources WHERE id_=990');
workCheck(!$repo->listing(1,50)['files'],'Withdrawing a project source also withdraws its JSON from the panel');
$db->query("UPDATE ChatSessions SET project_id_=501 WHERE id_=50");
$denied=false;try{$repo->listing(1,50,'project');}catch(DocumentAccessDenied){$denied=true;}workCheck($denied,'Forged project FK cannot expose another owner project');
$db->query("UPDATE ChatSessions SET project_id_=500,meta='{}' WHERE id_=50");
for($i=0;$i<55;$i++)$catalog->created(1,'Data/panel/generated-'.$i.'.json',2,'application/json','generated-'.$i.'.json','fixture',50);
$page=$repo->listing(1,50);$next=$repo->listing(1,50,'session',$page['next_offset']);
workCheck(count($page['files'])===50&&count($next['files'])===$page['total']-50&&!array_intersect(array_column($page['files'],'id'),array_column($next['files'],'id')),'Panel paginates outputs without duplicates');
$db->query("UPDATE ChatSessions SET status='closed' WHERE id_=51");
workCheck(!in_array((int)$second['id_'],array_column($repo->listing(1,50,'project')['files'],'id'),true),'Deleted conversation is excluded from project scope');
echo "OK conversation data: actual JSON, scope, ownership, revocation, unlink and pagination\n";
